// Visible Session Volume Profile with POC Value Area Breakout
// Volume-at-price bins over visible session, POC + 70% value area expansion.

numBins = input(24, "Profile Rows", 10, 48, 1)
vaPercent = input(70, "Value Area %", 50, 90, 5)
sessCap = input(250, "Session Bars", 50, 500, 10)
showVA = input(true, "Show Value Area")
showPOC = input(true, "Show POC Rail")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// --- Visible session window (from first bar, capped for performance) ---
sessLen = bar_index + 1
effLen = sessLen
if effLen > sessCap { effLen := sessCap }
if effLen < 24 { effLen := sessLen }

// --- Session range ---
hh = highest(high, effLen)
ll = lowest(low, effLen)
rng = hh - ll
if rng <= 0 { rng := close * 0.01 }

// --- Build profile bins from scratch each bar ---
binVol = array()
b = 0
while b < numBins {
    array.push(binVol, 0.0)
    b := b + 1
}

totalVol = 0.0
j = 0
while j < effLen {
    hb = high[j]
    lb = low[j]
    vb = volume[j]
    totalVol := totalVol + vb
    bLo = floor((lb - ll) / rng * numBins)
    bHi = floor((hb - ll) / rng * numBins)
    if bLo < 0 { bLo := 0 }
    if bHi > numBins - 1 { bHi := numBins - 1 }
    if bLo > bHi { bLo := bHi }
    span = bHi - bLo + 1
    share = 0.0
    if span > 0 { share := vb / span }
    k = bLo
    while k <= bHi {
        array.set(binVol, k, array.get(binVol, k) + share)
        k := k + 1
    }
    j := j + 1
}

// --- POC: bin with highest volume ---
pocBin = 0
pocVal = array.get(binVol, 0)
i = 1
while i < numBins {
    v = array.get(binVol, i)
    if v > pocVal {
        pocVal := v
        pocBin := i
    }
    i := i + 1
}
pocPrice = ll + (pocBin + 0.5) / numBins * rng
pocShare = 0.0
if totalVol > 0 { pocShare := pocVal / totalVol }

// --- Value area: expand from POC until >= vaPercent of total ---
vaLow = pocBin
vaHigh = pocBin
accum = pocVal
target = totalVol * vaPercent / 100
guard = 0
while accum < target and guard < numBins {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(binVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < numBins - 1 { rightVal := array.get(binVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < numBins - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        } else {
            if vaHigh < numBins - 1 {
                vaHigh := vaHigh + 1
                accum := accum + rightVal
            }
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHigh + 1) / numBins * rng
valPrice = ll + vaLow / numBins * rng

// --- Volume at close's bin = terrain height ---
closeBin = floor((close - ll) / rng * numBins)
if closeBin < 0 { closeBin := 0 }
if closeBin > numBins - 1 { closeBin := numBins - 1 }
binHeight = array.get(binVol, closeBin)
binHeightN = 0.0
if pocVal > 0 { binHeightN := binHeight / pocVal * close }

// --- Signals: price leaving value ---
insideNow = close >= valPrice and close <= vahPrice
prevVAH = vahPrice[1]
prevVAL = valPrice[1]
insidePrev = close[1] >= prevVAL and close[1] <= prevVAH
buySig = close > vahPrice and insidePrev
sellSig = close < valPrice and insidePrev

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
    model.longEntry("VPBreakUp")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
    model.shortEntry("VPBreakDn")
}

// --- 2D: identical POC/VAH/VAL levels when 3D is off ---
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(binHeight, "Bin Volume", "#4488ff", 1, "separate")

// --- 2D profile histogram bars on chart (right-edge boxes) ---
bi = 0
while bi < numBins {
    bTop = ll + (bi + 1) / numBins * rng
    bBot = ll + bi / numBins * rng
    inVA = bi >= vaLow and bi <= vaHigh
    isPOC = bi == pocBin
    bc = "rgba(68,136,255,0.25)"
    if inVA { bc := "rgba(34,204,136,0.35)" }
    if isPOC { bc := "rgba(255,212,59,0.55)" }
    box.new(bar_index - effLen + 1, bTop, bar_index, bBot, bc, bc, 1)
    bi := bi + 1
}

// --- 3D: value terrain + POC labelled rail + VAH/VAL boundary walls ---
plot3d(binHeight, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Wall", "line3d", "#22cc88", "3d", 2)
label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.0, 1, "3d")

if insideNow { bgcolor("rgba(34,204,136,0.05)") }

// FIX 1: var lvl = highest(high, 20) froze the level on bar 0 — changed to plain assignment so it recomputes every bar.
// FIX 2: close[-1] indexed the future (lookahead) — changed to close > lvl for a current-bar breakout.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) was Pine signature/constants — changed to OakScript positional plotshape(bar_index, price, title, style, color).
// FIX 4: plot3d RSI into pane "3d" forced an oscillator into the price scene (spiky forest) — changed to pane "separate" per PANE LAW.
// FIX 5: added missing 2D plot() twin and SAME-pane plotshape_3d cones so the model renders in both 2D and 3D modes.
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
if buySig {
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, "separate")
}
if osSig {
    plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", markerSize, "separate")
}
plot(lvl, "High20", "#ffcc44", 1, "stepline")
plot(r, "RSI", "#b48cff", 1)
plot3d(r, "RSI", "surface", "#b48cff", "separate")

psiScale = input(1.5, "PSI Scale", 0.5, 3.0, 0.1)
crit = input(150, "Critical Threshold", 50.0, 300.0, 1.0)
spin_factor = input(0.5, "Spin Factor", 0.1, 2.0, 0.1)
ring_count = input(3, "Ring Count", 1.0, 5.0, 1.0)
ring_expansion_rate = input(2.0, "Ring Expansion Rate", 0.5, 6.0, 0.5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = close * psiScale + (high - low) * 0.5 * psiScale
spin_speed = spin_factor * flow_psi
locked = flow_psi > crit
overState = flow_psi > crit
perimR = 10.0
maxR = 10.0 + 12.0
rangeBar = high - low
critLine = crit + rangeBar * 0.1

var discAngle = 0.0
var rr = 0.0

if locked {
    discAngle := discAngle[1]
} else {
    discAngle := discAngle[1] + spin_speed
}

if locked {
    if rr[1] + ring_expansion_rate > maxR {
        rr := perimR
    } else {
        rr := rr[1] + ring_expansion_rate
    }
} else {
    rr := 0.0
}

discSpin3d = flow_psi + discAngle * 0.05
shock3d = flow_psi + rr

overSig = overState and not overState[1]
clearSig = not overState and overState[1]
shockA_sig = overState and not overState[1]
shockB_sig = overState and overState[1] and not overState[2]
shockC_sig = overState and overState[1] and overState[2] and not overState[3]

if overSig {
    plotshape(bar_index, high, "OVERPRESSURE", "triangledown", "#ff4477")
}

if clearSig {
    plotshape(bar_index, low, "Clear", "triangleup", "#22cc88")
}

if shockA_sig {
    plotshape_3d(bar_index, high, "ShockA", "torus", "#ff4477", 1.0 * markerSize, 0, "separate", 90.0, discAngle, 0.0)
}

if shockB_sig {
    plotshape_3d(bar_index, high, "ShockB", "torus", "#ffaa00", 1.8 * markerSize, 1, "separate", 90.0, discAngle, 0.0)
}

if shockC_sig {
    plotshape_3d(bar_index, high, "ShockC", "torus", "#ff4477", 2.6 * markerSize, 2, "separate", 90.0, discAngle, 0.0)
}

if overSig {
    label3d(bar_index, high, "OVERPRESSURE", "#ff4477", 1, 3, "separate")
}

plot(flow_psi, "Flow PSI", "#22aaff", 2, "separate")
plot(critLine, "Critical 150", "#ff4477", 1, "separate")
plot(discSpin3d, "Disc Spin", "#33ddff", 1, "separate")
plot(shock3d, "Shock Radius", "#ffaa00", 1, "separate")
plot3d(discSpin3d, "Valve Disc", "torus", "#22aaff", "separate", 0)
plot3d(shock3d, "Shockwave", "trail", "#ff4477", "separate", 1)
